+                .put(TieredStoreMetricsConstant.LABEL_QUEUE, messageQueue.getQueueId())
+                .put(TieredStoreMetricsConstant.LABEL_FILE_TYPE, TieredFileSegment.FileSegmentType.CONSUME_QUEUE.name().toLowerCase())
