+    }
+
+    @Override
+    public String getServiceName() {
+        return "TieredStoreDispatcherService";
+    }
+
+    @Override
+    public void run() {
+        while (!stopped) {
+            waitForRunning(1000);
+            try {
+                buildCQAndIndexFile();
+            } catch (Exception e) {
+                logger.error("build consumeQueue and indexFile failed: ", e);
+            }
+        }
+    }
