+                        result.add(Pair.of(fileSegment.getBeginTimestamp(), indexBuffer));
+                    }
+                    return result;
+                });
+            } else {
+                future = future.thenCombine(tmpFuture, (indexList, indexBuffer) -> {
+                    if (indexBuffer != null) {
+                        indexList.add(Pair.of(fileSegment.getBeginTimestamp(), indexBuffer));
+                    }
+                    return indexList;
+                });
+            }
