+                    TieredStoreMetricsManager.providerRpcLatency.record(costTime, attributesBuilder.build());
+
+                    Attributes metricsAttributes = newAttributesBuilder()
+                        .put(LABEL_OPERATION, OPERATION_POSIX_WRITE)
